getValueOfRange(range) {
        if (range.startLineNumber === range.endLineNumber) {
            return this.d(range.startLineNumber).substring(range.startColumn - 1, range.endColumn - 1);
        }
        let result = this.d(range.startLineNumber).substring(range.startColumn - 1);
        for (let i = range.startLineNumber + 1; i < range.endLineNumber; i++) {
            result += '\n' + this.d(i);
